package com.kholodilin.repogrowth.publication;
import com.kholodilin.repogrowth.support.AbstractPostgresTest;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.assertj.core.api.Assertions.*;
class PublicationIT extends AbstractPostgresTest {
 @Autowired JdbcTemplate jdbc;@Autowired PublicationService service;long owner,repo;
 @BeforeEach void setup(){jdbc.execute("TRUNCATE github_owner_alias,repository_path_alias");jdbc.execute("TRUNCATE repository,github_owner CASCADE");owner=jdbc.queryForObject("INSERT INTO github_owner(github_id,login,owner_type) VALUES(101,'ExampleOrg','ORGANIZATION') RETURNING id",Long.class);repo=insert(202,"Project");}
 long insert(long github,String name){return jdbc.queryForObject("INSERT INTO repository(github_id,owner_id,name,full_name,visibility,tracking_enabled) VALUES(?,?,?,?,'PUBLIC',false) RETURNING id",Long.class,github,owner,name,"ExampleOrg/"+name);}
 void publish(){service.verify(repo,202,"PUBLIC",Instant.now());service.publish(repo,new PublicationService.Policy(true,true,false,false,true));}
 @Test void defaultsAreOffAndTrackingIsIndependent(){assertThat(service.eligible(repo)).isFalse();assertThat(jdbc.queryForObject("SELECT public_traffic_enabled FROM repository WHERE id=?",Boolean.class,repo)).isFalse();}
 @Test void orgCaseTrailingSlashAndRevocation(){publish();var resolved=service.resolve("/exampleorg/project/");assertThat(resolved.repositoryId()).isEqualTo(repo);assertThat(resolved.canonicalPath()).isEqualTo("/ExampleOrg/Project");assertThat(resolved.redirect()).isTrue();assertThat(service.resolve("/ExampleOrg").ownerId()).isEqualTo(owner);service.publish(repo,new PublicationService.Policy(false,true,false,false,true));assertThatThrownBy(()->service.resolve("/ExampleOrg/Project")).hasMessage("Page not found");}
 @Test void privateUnknownUnpublishedAndExpiredAreIndistinguishable(){publish();service.verify(repo,202,"PRIVATE",Instant.now());assertThatThrownBy(()->service.resolve("/ExampleOrg/Project")).hasMessage("Page not found");assertThatThrownBy(()->service.resolve("/missing/repo")).hasMessage("Page not found");jdbc.update("UPDATE repository SET visibility='PUBLIC',visibility_verified_at=clock_timestamp()-interval '25 hours'");assertThat(service.eligible(repo)).isFalse();assertThatThrownBy(()->service.resolve("/ExampleOrg")).hasMessage("Page not found");}
 @Test void wrongGitHubIdCannotConfirmAndOldObservationCannotUndoPrivate(){assertThat(service.verify(repo,999,"PUBLIC",Instant.now())).isFalse();publish();Instant before=Instant.now().minusSeconds(60);service.verify(repo,202,"PRIVATE",Instant.now());assertThat(service.verify(repo,202,"PUBLIC",before)).isFalse();assertThat(service.eligible(repo)).isFalse();}
 @Test void renameAndTransferKeepStableHistoryIdentity(){publish();jdbc.update("INSERT INTO traffic_daily(repository_id,traffic_date,views,unique_visitors,clones,unique_cloners) VALUES (?,CURRENT_DATE,17,3,4,2)",repo);jdbc.update("UPDATE repository SET name='Renamed',full_name='ExampleOrg/Renamed' WHERE id=?",repo);assertThat(service.resolve("/ExampleOrg/Project").repositoryId()).isEqualTo(repo);jdbc.update("UPDATE github_owner SET login='NewOrg' WHERE id=?",owner);assertThat(service.resolve("/ExampleOrg").canonicalPath()).isEqualTo("/NewOrg");assertThat(service.resolve("/ExampleOrg/Project").canonicalPath()).isEqualTo("/NewOrg/Renamed");assertThat(jdbc.queryForObject("SELECT full_name FROM repository WHERE id=?",String.class,repo)).isEqualTo("NewOrg/Renamed");long other=jdbc.queryForObject("INSERT INTO github_owner(github_id,login,owner_type) VALUES(303,'OtherOrg','ORGANIZATION') RETURNING id",Long.class);jdbc.update("UPDATE repository SET owner_id=?,full_name='OtherOrg/Renamed' WHERE id=?",other,repo);assertThat(service.resolve("/NewOrg/Renamed").canonicalPath()).isEqualTo("/OtherOrg/Renamed");assertThat(jdbc.queryForObject("SELECT views FROM traffic_daily WHERE repository_id=?",Integer.class,repo)).isEqualTo(17);}
 @Test void canonicalReuseHidesOldAliasEvenWhenNewEntityIsNotPublished(){publish();jdbc.update("UPDATE repository SET name='NewName' WHERE id=?",repo);insert(303,"Project");assertThatThrownBy(()->service.resolve("/ExampleOrg/Project")).hasMessage("Page not found");assertThat(service.resolve("/ExampleOrg/NewName").repositoryId()).isEqualTo(repo);}
 @Test void unsafeAndFuturePathsAreNotResolved(){publish();for(String path:new String[]{"/api","/ADMIN/repo","/ExampleOrg/Project/wrapped","/ExampleOrg/badge/stars.svg","/ExampleOrg/%2f","/ExampleOrg/..","/ExampleOrg/Project?x=1","//ExampleOrg"})assertThatThrownBy(()->service.resolve(path)).hasMessage("Page not found");long badge=insert(404,"badge");service.verify(badge,404,"PUBLIC",Instant.now());service.publish(badge,new PublicationService.Policy(true,false,false,false,false));assertThat(service.resolve("/ExampleOrg/badge").repositoryId()).isEqualTo(badge);}
 @Test void normalizedIndexesAndAliasConflictFailWithoutChangingTarget(){publish();assertThatThrownBy(()->insert(303,"project")).isInstanceOf(org.springframework.dao.DataAccessException.class);jdbc.update("UPDATE repository SET name='Next' WHERE id=?",repo);long second=insert(404,"Other");jdbc.update("UPDATE repository SET name='Project' WHERE id=?",second);assertThatThrownBy(()->jdbc.update("UPDATE repository SET name='Again' WHERE id=?",second)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT repository_id FROM repository_path_alias WHERE repository_name='Project'",Long.class)).isEqualTo(repo);}
 @Test void reservedOwnerCannotBePublished(){jdbc.update("UPDATE github_owner SET login='admin' WHERE id=?",owner);assertThatThrownBy(()->service.publish(repo,new PublicationService.Policy(true,false,false,false,false))).hasMessageContaining("reserved");}
 @Test void moduleAndQueryPublicationNeverBypassParent(){publish();assertThat(service.allows(repo,PublicationService.Module.TRAFFIC)).isTrue();assertThat(service.allows(repo,PublicationService.Module.PATHS)).isFalse();long query=jdbc.queryForObject("INSERT INTO search_query(repository_id,name,query,enabled,result_limit) VALUES (?,'query','stars:>1',true,50) RETURNING id",Long.class,repo);assertThat(service.queryEligible(query)).isFalse();long before=jdbc.queryForObject("SELECT publication_revision FROM repository WHERE id=?",Long.class,repo);jdbc.update("UPDATE search_query SET public_enabled=true WHERE id=?",query);assertThat(service.queryEligible(query)).isTrue();assertThat(jdbc.queryForObject("SELECT publication_revision FROM repository WHERE id=?",Long.class,repo)).isGreaterThan(before);service.publish(repo,new PublicationService.Policy(false,true,true,true,true));assertThat(service.queryEligible(query)).isFalse();assertThat(service.allows(repo,PublicationService.Module.TRAFFIC)).isFalse();}
 @Test void revisionChangesForPolicyButNotTracking(){publish();long revision=jdbc.queryForObject("SELECT publication_revision FROM repository WHERE id=?",Long.class,repo);jdbc.update("UPDATE repository SET tracking_enabled=true WHERE id=?",repo);assertThat(jdbc.queryForObject("SELECT publication_revision FROM repository WHERE id=?",Long.class,repo)).isEqualTo(revision);service.publish(repo,new PublicationService.Policy(true,false,false,false,true));assertThat(jdbc.queryForObject("SELECT publication_revision FROM repository WHERE id=?",Long.class,repo)).isGreaterThan(revision);}
 @Test void reservedRegistryMatchesFrontendContract()throws Exception{var json=tools.jackson.databind.json.JsonMapper.builder().build();var fixture=java.nio.file.Path.of("../frontend/test-fixtures/reserved-public-segments.json");var values=json.readValue(java.nio.file.Files.readString(fixture),String[].class);assertThat(PublicRoutes.RESERVED).containsExactlyInAnyOrder(values);}
 @Test void ownerAliasAlsoFindsLaterRepositoryAliases(){publish();jdbc.update("UPDATE github_owner SET login='NewOrg' WHERE id=?",owner);long added=insert(909,"Later");service.verify(added,909,"PUBLIC",Instant.now());service.publish(added,new PublicationService.Policy(true,false,false,false,false));jdbc.update("UPDATE repository SET name='Latest' WHERE id=?",added);assertThat(service.resolve("/ExampleOrg/Later").canonicalPath()).isEqualTo("/NewOrg/Latest");}
}
